use futures::TryStreamExt;
use ngano::{Catalogue, Loader};

/// The catalogue record for {{DATASET_ID}}, then its rows.
pub async fn ngano_dataset() -> Result<(), ngano::NganoError> {
    let cat = Catalogue::bundled()?;

    let d = cat.require("{{DATASET_ID}}")?;
    println!("{} ({}, {})", d.name, d.licence, d.access);
    println!("{}", d.notes);

    let mut stream = Loader::new()
        .catalogue(cat.clone())
        .dataset("{{DATASET_ID}}")
        .split("train")
        .hf_token(std::env::var("HF_TOKEN").ok())
        .limit(Some(100))
        .stream()
        .await?;

    while let Some(row) = stream.try_next().await? {
        println!("{:?}", row.transcript.as_deref());
    }
    Ok(())
}
